<template><view class="ui11-page"><view class="ui11-nav"><navigator open-type="navigateBack" class="ui11-nav__back">‹</navigator><text class="ui11-nav__title">选择药品</text><text class="ui11-nav__placeholder"></text></view><view class="form"><view class="ui11-row"><text class="ui11-row__label">药品名称</text><input v-model="form.medicineName" class="ui11-input" placeholder="请输入药品名称"/></view><view class="ui11-row"><text class="ui11-row__label">用药剂量</text><input v-model="form.dosage" class="ui11-input" placeholder="例如：1片"/></view><view class="ui11-row"><text class="ui11-row__label">用药时间</text><input v-model="form.takenAt" class="ui11-input" placeholder="请选择时间"/></view></view><view class="ui11-fixed-action"><view class="ui11-primary-btn" @click="submit">{{loading?'保存中…':'确定'}}</view></view></view></template>
<script>import { saveMedicine } from '@/api/health.js'; export default {data(){return{loading:false,form:{medicineName:'',dosage:'',takenAt:''}}},methods:{submit(){if(!this.form.medicineName)return uni.showToast({title:'请填写药品名称',icon:'none'});this.loading=true;saveMedicine(this.form).then(()=>uni.showToast({title:'保存成功',icon:'success'})).catch(()=>uni.showToast({title:'健康服务暂未接入',icon:'none'})).finally(()=>this.loading=false)}}}</script>
<style lang="scss" scoped>.form{padding:0 12rpx;background:#fff}.ui11-input{flex:1;text-align:right;font-size:30rpx}</style>
